--
-- Name: apply_surveys_policies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_surveys_policies() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$

BEGIN

  -- Habilitar RLS en la tabla surveys

  ALTER TABLE surveys ENABLE ROW LEVEL SECURITY;

  

  -- Eliminar pol├¡ticas existentes

  DROP POLICY IF EXISTS "Usuarios autenticados pueden leer encuestas" ON surveys;

  DROP POLICY IF EXISTS "Admins y supervisores pueden crear encuestas" ON surveys;

  DROP POLICY IF EXISTS "Admins y supervisores pueden actualizar encuestas" ON surveys;

  DROP POLICY IF EXISTS "Usuarios pueden crear encuestas" ON surveys;

  DROP POLICY IF EXISTS "Usuarios pueden actualizar sus encuestas" ON surveys;

  DROP POLICY IF EXISTS "Usuarios pueden eliminar sus encuestas" ON surveys;

  

  -- Crear pol├¡ticas

  -- Pol├¡tica para que todos los usuarios autenticados puedan leer encuestas

  CREATE POLICY "Usuarios autenticados pueden leer encuestas"

  ON surveys FOR SELECT

  TO authenticated

  USING (true);

  

  -- Pol├¡tica para que todos los usuarios autenticados puedan crear encuestas

  CREATE POLICY "Usuarios pueden crear encuestas"

  ON surveys FOR INSERT

  TO authenticated

  WITH CHECK (true);

  

  -- Pol├¡tica para que los usuarios puedan actualizar sus propias encuestas

  CREATE POLICY "Usuarios pueden actualizar sus encuestas"

  ON surveys FOR UPDATE

  TO authenticated

  USING (created_by = auth.uid());

  

  -- Pol├¡tica para que los usuarios puedan eliminar sus propias encuestas

  CREATE POLICY "Usuarios pueden eliminar sus encuestas"

  ON surveys FOR DELETE

  TO authenticated

  USING (created_by = auth.uid());

END;

$$;


--
-- Name: prevent_id_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_id_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

    -- Si se est├í intentando cambiar el ID, lanzar error

    IF OLD.id != NEW.id THEN

        RAISE EXCEPTION 'No se puede cambiar el ID de una secci├│n. ID original: %, ID nuevo: %', OLD.id, NEW.id;

    END IF;

    

    -- Permitir la actualizaci├│n de otros campos

    RETURN NEW;

END;

$$;


--
-- Name: prevent_questions_id_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_questions_id_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

    -- Verificar si el ID est├í siendo cambiado

    IF OLD.id IS DISTINCT FROM NEW.id THEN

        RAISE EXCEPTION 'No se permite cambiar el ID de la tabla questions. El ID original era: %, el nuevo ID es: %', 

                       OLD.id, NEW.id;

    END IF;

    

    -- Si no hay cambio en el ID, permitir la operaci├│n

    RETURN NEW;

END;

$$;


